export const SHOWROOM_MANUFACTURERS=Object.freeze(publicManufacturers.map(manufacturer=>Object.freeze({
 ...manufacturer,href:showroomAssetURL(manufacturer.href),url:showroomAssetURL(manufacturer.href),logo:showroomAssetURL(manufacturer.logo),
 collections:Object.freeze(manufacturer.collections.map(collection=>Object.freeze({
  ...collection,image:showroomAssetURL(collection.image),preview:showroomAssetURL(collection.preview||collection.image),
  href:showroomAssetURL(collection.href),url:showroomAssetURL(collection.href),
  ...(collection.formats?{formats:Object.freeze(collection.formats)}:{}),
  ...(collection.colors?{colors:Object.freeze(collection.colors)}:{})
 })))
})));
export const SHOWROOM_COLLECTIONS=Object.freeze(SHOWROOM_MANUFACTURERS.flatMap(manufacturer=>manufacturer.collections.map(collection=>Object.freeze({...collection,manufacturerId:manufacturer.id,manufacturerName:manufacturer.name}))));
export function showroomManufacturer(id){return SHOWROOM_MANUFACTURERS.find(manufacturer=>manufacturer.id===id)||null;}
